						if action.Kind != "press" {
							return false
						}
						return applyAccessibilityAction(r, accessibilityAction{Kind: "set", Value: optionID})
					}
				}
				nodes = append(nodes, child)
			}
		}
		for _, c := range r.children {
			if n.Kind == ui.Tabs && c.node.ID != n.SelectedID {
