	fonts := fontMemoryFS{MapFS: fstest.MapFS{}}
	total := 0
	copied := make([]ManualFont, len(config.Fonts))
	for i, f := range config.Fonts {
		if !fs.ValidPath(f.Name) || f.Name == "." || fonts.MapFS[f.Name] != nil || len(f.Data) == 0 || len(f.Data) > 4<<20 {
